def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""

    result = []
    current_char = texto[0]
    count = 1

    for char in texto[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")
    return "".join(result)

def iniciales(nombre: str) -> str:
    # Separar palabras por cualquier espacio en blanco
    palabras = nombre.split()
    # Concatenar las primeras letras en mayúscula
    return ''.join(palabra[0].upper() for palabra in palabras)

def aplanar(datos: list) -> list:
    def flatten(item):
        if isinstance(item, (list, tuple)):
            flat_parts = []
            for sub in item:
                flat_parts.extend(flatten(sub))
            return flat_parts
        else:
            return [item]

    result = []
    for item in datos:
        result.extend(flatten(item))
    return result

import csv
from io import StringIO

def parsear_ventas(texto: str) -> list[dict]:
    # Crear un objeto in-memory para el archivo
    buffer = StringIO(texto)
    reader = csv.reader(buffer)

    try:
        header = next(reader)
    except StopIteration:
        return []

    # Verificar la cabecera
    if header != ['fecha', 'producto', 'cantidad', 'precio']:
        raise ValueError("Cabecera no compatible.")

    resultado = []
    for row in reader:
        # Ignorar líneas vacías
        if not row or all(field.strip() == '' for field in row):
            continue

        # Verificar que haya 4 campos
        if len(row) != 4:
            raise ValueError("Fila con incorrecto número de campos.")

        fecha, producto, cantidad_str, precio_str = row

        # Convert cantidad
        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError("cantidad no es un entero.")
        if cantidad < 0:
            raise ValueError("cantidad no puede ser negativa.")

        # Convert precio
        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError("precio no es un número.")

        resultado.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })

    return resultado

def parsear_fecha(texto: str) -> str:
    import re
    from datetime import date

    texto = texto.strip()
    year = month = day = None
    mensaje_error = None

    # Formato 3: D de MES de AAAA
    if " de " in texto:
        partes = texto.split(" de ")
        if len(partes) != 3:
            mensaje_error = "Formato 3: No exactamente 3 partes separadas."
        else:
            día_str, mes_str, año_str = partes
            try:
                day = int(día_str)
                # Verificar mes en español
                mes_map = {
                    "enero": 1, "febrero": 2, "marzo": 3, "abril": 4,
                    "mayo": 5, "junio": 6, "julio": 7, "agosto": 8,
                    "septiembre": 9, "octubre": 10, "noviembre": 11, "diciembre": 12
                }
                mes_str_lower = mes_str.lower()
                month = mes_map.get(mes_str_lower)
                if month is None:
                    mensaje_error = "Formato 3: Mes no válido."
                year = int(año_str)
            except ValueError:
                mensaje_error = "Formato 3: Día o año no numéricos."
    # Formato 2: DD/MM/AAAA
    elif "/" in texto:
        partes = texto.split("/")
        if len(partes) != 3:
            mensaje_error = "Formato 2: No exactamente 3 partes separadas."
        else:
            try:
                day = int(partes[0])
                month = int(partes[1])
                year = int(partes[2])
            except ValueError:
                mensaje_error = "Formato 2: Día, mes o año no numéricos."
    # Formato 1: AAAA-MM-DD
    else:
        partes = texto.split("-")
        if len(partes) != 3:
            mensaje_error = "Formato 1: No exactamente 3 partes separadas."
        else:
            try:
                year = int(partes[0])
                month = int(partes[1])
                day = int(partes[2])
            except ValueError:
                mensaje_error = "Formato 1: Día, mes o año no numéricos."

    if mensaje_error:
        raise ValueError(mensaje_error)

    # Verificar que la fecha sea válida (considerando años bisiestos)
    try:
        fecha = date(year, month, day)
    except ValueError:
        raise ValueError("Fecha no existe (día inválido o año bisiesto no ajustado).")

    return f"{year}-{month:02d}-{day:02d}"

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    # Validate inputs
    if len(pesos) != len(valores):
        raise ValueError("pesos y valores deben tener la misma longitud")
    if capacidade < 0:
        raise ValueError("capacidad no puede ser negativa")
    for w in pesos:
        if w < 0:
            raise ValueError("pesos no puede tener valores negativos")

    n = len(pesos)
    best = []  # list of (value, weight, count, indices)

    # Generate all subsets using bitmask
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        count = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                count += 1
                indices.append(i)
        if total_weight <= capacidad:
            best.append((total_value, total_weight, count, indices))

    if not best:
        return (0, [])

    # Sort by: descending value, ascending weight, ascending count, ascending indices (lexicographic)
    best.sort(key=lambda x: (-x[0], x[1], x[2], x[3]))

    return (best[0][0], best[0][3])

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacity cannot be negative")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave not in self._datos:
            return None
        self._datos.move_to_end(clave)
        return self._datos[clave]

    def put(self, clave, valor):
        if self.capacidad <= 0:
            return
        if clave in self._datos:
            self._datos.move_to_end(clave)
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
        self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
